using System;
using System.ComponentModel;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Globalization;
using System.IO;
using System.Windows.Forms;
namespace ZenForms.Core
{
    public sealed class ZenWaveformErrorEventArgs : EventArgs { public string Message { get; private set; } public ZenWaveformErrorEventArgs(string message) { Message = message; } }
    public sealed class ZenWaveSeekEventArgs : EventArgs { public double PositionSeconds { get; private set; } public ZenWaveSeekEventArgs(double seconds) { PositionSeconds = seconds; } }
    [Category("ZenForms Modern Components")]
    [Description("WAV PCM/IEEE-float analyzer with wave form.")]
    public class ZenWaveformAnalyzer : UserControl
    {
        private readonly WaveSurface surface; private readonly Label status; private readonly Button open; private float[] minimum = new float[0], maximum = new float[0]; private double duration; private int sampleRate, channels; private Color waveColor = ZenTheme.Accent; private double cursor;
        [Category("ZenForms Audio")] public Color WaveColor { get { return waveColor; } set { waveColor = value; surface.Invalidate(); } }
        [Browsable(false)] public double DurationSeconds { get { return duration; } }
        [Browsable(false)] public int SampleRate { get { return sampleRate; } }
        [Browsable(false)] public int Channels { get { return channels; } }
        [Browsable(false)] public double PositionSeconds { get { return cursor; } }
        public event EventHandler<ZenWaveSeekEventArgs> SeekRequested;
        public event EventHandler<ZenWaveformErrorEventArgs> LoadError;
        public ZenWaveformAnalyzer() { Size = new Size(720, 250); BackColor = ZenTheme.Background; Panel bar = new Panel { Dock = DockStyle.Top, Height = 38, BackColor = ZenTheme.Surface }; open = new Button { Dock = DockStyle.Left, Width = 108, Text = "Open WAV…", FlatStyle = FlatStyle.Flat, BackColor = ZenTheme.SurfaceRaised, ForeColor = ZenTheme.Foreground }; status = new Label { Dock = DockStyle.Fill, Text = "Open a WAV PCM file or IEEE-float", ForeColor = ZenTheme.Muted, TextAlign = ContentAlignment.MiddleLeft, Padding = new Padding(10, 0, 0, 0) }; bar.Controls.Add(status); bar.Controls.Add(open); surface = new WaveSurface(this) { Dock = DockStyle.Fill, BackColor = Color.FromArgb(12, 16, 28) }; Controls.Add(surface); Controls.Add(bar); open.Click += (s, e) => OpenFile(); }
        public void LoadWave(string path) { try { ReadWave(path); cursor = 0; status.Text = Path.GetFileName(path) + "   •   " + sampleRate.ToString("N0") + " Hz   •   " + channels + " ch   •   " + TimeSpan.FromSeconds(duration).ToString(@"mm\:ss"); surface.Invalidate(); } catch (Exception ex) { minimum = maximum = new float[0]; status.Text = "Wasn't possible open WAV file"; surface.Invalidate(); EventHandler<ZenWaveformErrorEventArgs> h = LoadError; if (h != null) h(this, new ZenWaveformErrorEventArgs(ex.Message)); else MessageBox.Show(FindForm(), ex.Message, "ZenWaveformAnalyzer", MessageBoxButtons.OK, MessageBoxIcon.Warning); } }
        private void OpenFile() { using (OpenFileDialog d = new OpenFileDialog { Filter = "WAV|*.wav|All|*.*", CheckFileExists = true }) if (d.ShowDialog(FindForm()) == DialogResult.OK) LoadWave(d.FileName); }
        private void ReadWave(string path) { using (FileStream fs = File.OpenRead(path)) using (BinaryReader br = new BinaryReader(fs)) { if (fs.Length < 44 || new string(br.ReadChars(4)) != "RIFF") throw new InvalidDataException("RIFF file ivalid."); br.ReadUInt32(); if (new string(br.ReadChars(4)) != "WAVE") throw new InvalidDataException("This isn't a WAV file."); ushort format = 0, bits = 0; int blockAlign = 0; long dataOffset = -1; uint dataBytes = 0; while (fs.Position + 8 <= fs.Length) { string id = new string(br.ReadChars(4)); uint size = br.ReadUInt32(); long start = fs.Position; if (id == "fmt ") { if (size < 16) throw new InvalidDataException("invalid Chunk fmt."); format = br.ReadUInt16(); channels = br.ReadUInt16(); sampleRate = (int)br.ReadUInt32(); br.ReadUInt32(); blockAlign = br.ReadUInt16(); bits = br.ReadUInt16(); } else if (id == "data") { dataOffset = start; dataBytes = size; } long next = start + size + (size % 2); if (next > fs.Length) throw new InvalidDataException("Chunk WAV corrupted."); fs.Position = next; } if (dataOffset < 0 || channels < 1 || sampleRate < 1 || blockAlign < 1) throw new InvalidDataException("This WAV is corrupted."); if (format != 1 && format != 3) throw new NotSupportedException("WAV format without support. Use PCM or IEEE-float files."); if (format == 3 && bits != 32) throw new NotSupportedException("This viewer accept float IEEE 32-bit."); if (format == 1 && bits != 8 && bits != 16 && bits != 24 && bits != 32) throw new NotSupportedException("PCM accepted: 8, 16, 24 or 32 bits."); long frames = dataBytes / (uint)blockAlign; if (frames <= 0) throw new InvalidDataException("WAV whitout example."); int buckets = (int)Math.Min(8192, frames); minimum = new float[buckets]; maximum = new float[buckets]; for (int i = 0; i < buckets; i++) { minimum[i] = 1; maximum[i] = -1; } fs.Position = dataOffset; for (long frame = 0; frame < frames; frame++) { double sum = 0; for (int ch = 0; ch < channels; ch++) sum += ReadSample(br, format, bits); float value = (float)Math.Max(-1, Math.Min(1, sum / channels)); int bucket = (int)(frame * buckets / frames); if (value < minimum[bucket]) minimum[bucket] = value; if (value > maximum[bucket]) maximum[bucket] = value; } duration = (double)frames / sampleRate; } }
        private static double ReadSample(BinaryReader r, ushort format, ushort bits) { if (format == 3) return r.ReadSingle(); switch (bits) { case 8: return (r.ReadByte() - 128) / 128.0; case 16: return r.ReadInt16() / 32768.0; case 24: { int b0 = r.ReadByte(), b1 = r.ReadByte(), b2 = r.ReadByte(); int v = b0 | (b1 << 8) | (b2 << 16); if ((v & 0x800000) != 0) v |= unchecked((int)0xFF000000); return v / 8388608.0; } default: return r.ReadInt32() / 2147483648.0; } }
        private sealed class WaveSurface : Control { private readonly ZenWaveformAnalyzer owner; public WaveSurface(ZenWaveformAnalyzer o) { owner = o; SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true); } protected override void OnMouseDown(MouseEventArgs e) { base.OnMouseDown(e); if (owner.duration <= 0) return; owner.cursor = Math.Max(0, Math.Min(owner.duration, (double)e.X / Math.Max(1, Width) * owner.duration)); Invalidate(); EventHandler<ZenWaveSeekEventArgs> h = owner.SeekRequested; if (h != null) h(owner, new ZenWaveSeekEventArgs(owner.cursor)); } protected override void OnPaint(PaintEventArgs e) { base.OnPaint(e); Graphics g = e.Graphics; g.SmoothingMode = SmoothingMode.AntiAlias; g.Clear(BackColor); if (owner.minimum.Length == 0) { TextRenderer.DrawText(g, "The wave form open here", Font, ClientRectangle, ZenTheme.Muted, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter); return; } float mid = Height / 2f; using (Pen center = new Pen(Color.FromArgb(50, ZenTheme.Muted))) g.DrawLine(center, 0, mid, Width, mid); using (Pen p = new Pen(owner.waveColor, 1f)) { for (int i = 0; i < owner.minimum.Length; i++) { int x = (int)((long)i * Width / owner.minimum.Length); float y1 = mid - owner.maximum[i] * (Height * .46f), y2 = mid - owner.minimum[i] * (Height * .46f); g.DrawLine(p, x, y1, x, y2); } } float pos = (float)(owner.cursor / owner.duration * Width); using (Pen marker = new Pen(Color.FromArgb(220, Color.White), 1.5f)) g.DrawLine(marker, pos, 0, pos, Height); string time = TimeSpan.FromSeconds(owner.cursor).ToString(@"mm\:ss"); using (Font timeFont = new Font("Consolas", 8f)) TextRenderer.DrawText(g, time, timeFont, new Rectangle(Math.Max(0, (int)pos - 25), 2, 50, 18), Color.White, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter); } }
    }
}

